const makeWalkthrough = (profile) => ({
  title: `От требования до проверенного результата: ${profile.title}`,
  context: `Этот разбор связывает архитектуру, Azure CLI и эксплуатацию. Цель — не повторить команды, а научиться безопасно менять ${profile.object}, доказывать результат и возвращаться к исходному состоянию при ошибке. Все изменения выполняются только в отдельной разрешённой лаборатории.`,
  steps: [
    `Сформулируйте требование через наблюдаемый результат: кто использует ${profile.object}, какой запрос должен пройти, какое состояние считается отказом и сколько времени допустимо на восстановление. Запишите подписку, tenant, resource group и владельца, чтобы не работать в неправильном контексте.`,
    `Снимите исходное состояние командами только для чтения из лаборатории и сохраните resource IDs. Сопоставьте вывод с порталом и Activity Log; если данные расходятся, остановитесь и сначала разберитесь с выбранной подпиской, правами, задержкой control plane и версией CLI.`,
    `Разработайте минимальное изменение и проверьте четыре ограничения: Azure RBAC, Azure Policy, сетевую доступность и стоимость. Для потенциальной потери доступа подготовьте отдельную административную сессию или другой путь управления, а также точную команду возврата к исходным параметрам.`,
    `Примените изменение к одному учебному ресурсу и сразу повторите чтение. Проверьте не только ProvisioningState, но и реальный пользовательский путь, профильную метрику, журнал и ожидаемое ограничение безопасности; успешный HTTP control-plane ответ ещё не доказывает работу приложения.`,
    `Если результат отличается, не вносите серию случайных правок. Пройдите цепочку identity → RBAC/Policy → DNS → route/NSG → состояние сервиса → приложение, фиксируя доказательство на каждом шаге. После исправления повторите тот же тест, которым обнаружили проблему.`,
    `Выполните очистку по resource IDs, проверьте содержимое resource group и Cost Management, затем оформите короткий отчёт: требование, схема, команды без секретов, фактический результат, проблема и способ отката. Такой отчёт становится рабочим runbook, а не одноразовым конспектом.`,
  ],
  verification: `${profile.expected} Дополнительно Activity Log не содержит неожиданных Failed-операций, а в учебной resource group не осталось бесхозных или тарифицируемых ресурсов после очистки.`,
  troubleshooting: `${profile.failure} Начинайте с проверки tenant и subscription, затем смотрите Azure Policy/RBAC, Activity Log и профильный диагностический инструмент. Меняйте за раз один параметр и всегда повторяйте первоначальную проверку, иначе нельзя доказать причинную связь.`,
});

export const azureCompletionLessons = Object.fromEntries(profiles.map((profile) => [profile.id, makeLesson(profile)]));
export const azureCompletionDetails = Object.fromEntries(profiles.map((profile) => [profile.id, makeDetail(profile)]));
export const azureCompletionWalkthroughs = Object.fromEntries(profiles.map((profile) => [profile.id, makeWalkthrough(profile)]));

